def fibonacci(n):
    &quot;&quot;&quot;计算斐波那契数列&quot;&quot;&quot;
    if n &amp;lt;= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def main():
    # 计算前20个斐波那契数
    for i in range(20):
        print(f&quot;F({i}) = {fibonacci(i)}&quot;)

