def fibonacci(n):
    &quot;&quot;&quot;计算斐波那契数列的第n项&quot;&quot;&quot;
    if n &amp;lt;= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for i in range(2, n + 1):
            a, b = b, a + b
        return b

